function readStoredRecord<T>(key: string, fallback: T): T {
  if (typeof window === "undefined") return fallback;
  try {
    const stored = window.localStorage.getItem(key);
    return stored ? (JSON.parse(stored) as T) : fallback;
  } catch {
    return fallback;
  }
}

function writeStoredValue(key: string, value: unknown) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // Local persistence is a convenience; the book remains usable without it.
  }
}

function dueText(word: VocabularyWord) {
  const due = new Date(word.nextReviewAt).getTime();
  const now = Date.now();
  if (due <= now) return "今天复习";
  const days = Math.max(1, Math.ceil((due - now) / 86_400_000));
  return `${days} 天后`;
}

function speakingSupported() {
  return typeof window !== "undefined" && "speechSynthesis" in window;
}

function speak(text: string) {
  if (!speakingSupported()) return false;
  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = "en-US";
  utterance.rate = 0.86;
  window.speechSynthesis.speak(utterance);
  return true;
}

function spellingDistance(left: string, right: string) {
  const rows = Array.from({ length: left.length + 1 }, (_, index) => [
    index,
    ...Array(right.length).fill(0),
  ]);
  for (let column = 0; column <= right.length; column += 1) {
    rows[0]![column] = column;
  }
  for (let row = 1; row <= left.length; row += 1) {
    for (let column = 1; column <= right.length; column += 1) {
      const cost = left[row - 1] === right[column - 1] ? 0 : 1;
      rows[row]![column] = Math.min(
        (rows[row - 1]![column] ?? 0) + 1,
        (rows[row]![column - 1] ?? 0) + 1,
        (rows[row - 1]![column - 1] ?? 0) + cost,
      );
    }
  }
  return rows[left.length]?.[right.length] ?? Math.max(left.length, right.length);
}

function coverStyle(theme: VocabularyCoverTheme, accent: string): CSSProperties {
  const selected =
    COVER_THEMES.find((item) => item.id === theme) ?? COVER_THEMES[0]!;
  return {
    "--wordbook-cover": selected.accent || accent,
    "--wordbook-cover-secondary": selected.secondary,
  } as CSSProperties;
}

function HighlightedText({
  text,
  term,
  active,
  onToggle,
}: {
  text: string;
  term: string;
  active: boolean;
  onToggle: () => void;
}) {
  const normalizedTerm = term.trim();
  if (!normalizedTerm) return text;
  const expression = new RegExp(
    `(${normalizedTerm.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})`,
    "gi",
  );
  const pieces = text.split(expression);
  return (
    <>
      {pieces.map((piece, index) =>
        piece.toLowerCase() === normalizedTerm.toLowerCase() ? (
          <mark
            key={`${piece}-${index}`}
            className={cn("wordbook-inline-mark", active && "is-active")}
            role="button"
            tabIndex={0}
            onClick={onToggle}
            onKeyDown={(event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                onToggle();
              }
            }}
          >
            {piece}
          </mark>
        ) : (
          <span key={`${piece}-${index}`}>{piece}</span>
        ),
      )}
    </>
  );
}

export function VocabularyPage() {
  const navigate = useNavigate();
  const corpus = useInkFlow((state) => state.corpus);
  const {
    initialized,
    book,
    words,
    reviewMode,
    reviewDirection,
    session,
    hydrate,
    updateBook,
    addInsight,
    addManyInsights,
    removeWord,
    setReviewMode,
    setReviewDirection,
    startReview,
    gradeCurrentWord,
    closeReview,
  } = useVocabulary();

  const [activeChapter, setActiveChapter] = useState<ChapterId>("all");
  const [query, setQuery] = useState("");
  const [selectedWordId, setSelectedWordId] = useState<string | null>(null);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [insertOpen, setInsertOpen] = useState(false);
  const [dictionaryQuery, setDictionaryQuery] = useState("");
  const [dictionaryResult, setDictionaryResult] =
    useState<LanguageInsight | null>(null);
  const [dictionaryLoading, setDictionaryLoading] = useState(false);
  const [dictionaryStatus, setDictionaryStatus] =
    useState<DictionaryStatus | null>(null);
  const [spellingInput, setSpellingInput] = useState("");
  const [spellingChecked, setSpellingChecked] = useState(false);
  const [flipped, setFlipped] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  const [bulkWords, setBulkWords] = useState("");
  const [turning, setTurning] = useState(false);
  const [turnKey, setTurnKey] = useState(0);
  const [bookmarkedIds, setBookmarkedIds] = useState<Set<string>>(
    () => new Set(readStoredRecord<string[]>(STORAGE_KEYS.bookmarks, [])),
  );
  const [highlightedIds, setHighlightedIds] = useState<Set<string>>(
    () => new Set(readStoredRecord<string[]>(STORAGE_KEYS.highlights, [])),
  );
  const [notes, setNotes] = useState<Record<string, string>>(() =>
    readStoredRecord<Record<string, string>>(STORAGE_KEYS.notes, {}),
  );
  const recordedReviewRef = useRef("");
  const noteRef = useRef<HTMLTextAreaElement | null>(null);
  const turnTimersRef = useRef<number[]>([]);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  useEffect(() => {
    void api
      .dictionaryStatus()
      .then(setDictionaryStatus)
      .catch(() =>
        setDictionaryStatus({
          available: false,
          name: null,
          wordCount: 0,
          reason: "API offline",
        }),
      );
  }, []);

  useEffect(() => {
    if (!notice) return;
    const timer = window.setTimeout(() => setNotice(null), 2600);
    return () => window.clearTimeout(timer);
  }, [notice]);

  useEffect(() => {
    writeStoredValue(STORAGE_KEYS.bookmarks, [...bookmarkedIds]);
  }, [bookmarkedIds]);

  useEffect(() => {
    writeStoredValue(STORAGE_KEYS.highlights, [...highlightedIds]);
  }, [highlightedIds]);

  useEffect(() => {
    writeStoredValue(STORAGE_KEYS.notes, notes);
  }, [notes]);

  useEffect(
    () => () => {
      turnTimersRef.current.forEach((timer) => window.clearTimeout(timer));
    },
    [],
  );

  useEffect(() => {
    if (!selectedWordId && words[0]) setSelectedWordId(words[0].id);
  }, [selectedWordId, words]);

  useEffect(() => {
    setFlipped(false);
    setSpellingInput("");
    setSpellingChecked(false);
  }, [session?.index, session?.round, session?.wordIds]);

  useEffect(() => {
    if (!session?.completed) return;
    const key = `${session.roundWordIds.join(",")}:${Object.values(
      session.ratings,
    )
      .flat()
      .join(",")}`;
    if (recordedReviewRef.current === key) return;
    recordedReviewRef.current = key;
    const passed = session.roundWordIds.filter(
      (wordId) =>
        (session.ratings[wordId]?.filter(
          (rating) => rating === "good" || rating === "easy",
        ).length ?? 0) >= 2,
    ).length;
    recordStudyEvent({
      kind: "word-review",
      at: Date.now(),
      reviewed: session.roundWordIds.length,
      passed,
      failed: Math.max(0, session.roundWordIds.length - passed),
    });
  }, [session]);

  const counts = useMemo(() => vocabularyMasteryCounts(words), [words]);
  const dueWords = useMemo(() => dueVocabularyWords(words), [words]);
  const normalizedQuery = query.trim().toLowerCase();
  const filteredWords = useMemo(() => {
    if (!normalizedQuery) return words;
    return words.filter((word) =>
      [
        word.term,
        word.definitionEn,
        word.meaningsZh.join(" "),
        word.sourceLabel,
        word.collocations.join(" "),
      ]
        .join(" ")
        .toLowerCase()
        .includes(normalizedQuery),
    );
  }, [normalizedQuery, words]);
  const chapterWords = useMemo(() => {
    if (activeChapter === "all") return filteredWords;
    if (activeChapter === "bookmarked") {
      return filteredWords.filter((word) => bookmarkedIds.has(word.id));
    }
    return filteredWords.filter((word) => word.mastery === activeChapter);
  }, [activeChapter, bookmarkedIds, filteredWords]);
  const selectedWord = useMemo(
    () =>
      chapterWords.find((word) => word.id === selectedWordId) ??
      chapterWords[0],
    [chapterWords, selectedWordId],
  );
  const currentSessionWord = useMemo(() => {
    if (!session || session.completed) return undefined;
    const id = session.wordIds[session.index];
    return words.find((word) => word.id === id);
  }, [session, words]);

  const currentWordIndex = selectedWord
    ? chapterWords.findIndex((word) => word.id === selectedWord.id)
    : -1;
  const currentChapter =
    chapterDefinitions.find((chapter) => chapter.id === activeChapter) ??
    chapterDefinitions[0]!;
  const activeChapterNumber =
    Math.max(
      1,
      chapterDefinitions.findIndex((chapter) => chapter.id === activeChapter) +
        1,
    ) * 2;

  const notify = (message: string) => setNotice(message);

  const turnPage = (update: () => void) => {
    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    if (reducedMotion) {
      update();
      setTurnKey((value) => value + 1);
      return;
    }
    turnTimersRef.current.forEach((timer) => window.clearTimeout(timer));
    setTurning(true);
    const updateTimer = window.setTimeout(() => {
      update();
      setTurnKey((value) => value + 1);
    }, 190);
    const finishTimer = window.setTimeout(() => setTurning(false), 560);
    turnTimersRef.current = [updateTimer, finishTimer];
  };

  const selectChapter = (chapterId: ChapterId) => {
    if (chapterId === activeChapter && !session) return;
    turnPage(() => {
      closeReview();
      setActiveChapter(chapterId);
      setSelectedWordId(null);
      setQuery("");
    });
  };

  const selectWord = (wordId: string) => {
    if (wordId === selectedWord?.id && !session) return;
    turnPage(() => {
      closeReview();
      setSelectedWordId(wordId);
    });
  };

  const toggleBookmark = (wordId: string) => {
    setBookmarkedIds((current) => {
      const next = new Set(current);
      if (next.has(wordId)) next.delete(wordId);
      else next.add(wordId);
      return next;
    });
  };

  const toggleHighlight = (wordId: string) => {
    setHighlightedIds((current) => {
      const next = new Set(current);
      if (next.has(wordId)) next.delete(wordId);
      else next.add(wordId);
      return next;
    });
  };

  const lookupDictionary = async (rawTerm: string) => {
    const term = rawTerm.trim();
    if (!term) return;
    setDictionaryLoading(true);
    try {
      const response = await api.dictionary(term);
      setDictionaryResult(response.insight);
    } catch {
      setDictionaryResult(fallbackInsight(term));
    } finally {
      setDictionaryLoading(false);
    }
  };

  const handleDictionarySearch = (event?: FormEvent<HTMLFormElement>) => {
    event?.preventDefault();
    void lookupDictionary(dictionaryQuery);
  };

  const handleDictionaryAdd = () => {
    if (!dictionaryResult) return;
    addInsight(dictionaryResult, "Oxford dictionary");
    setInsertOpen(false);
    setDictionaryResult(null);
    setDictionaryQuery("");
    setSelectedWordId(null);
    setActiveChapter("all");
    notify(`已收录：${dictionaryResult.term}`);
  };

  const handleBulkWordImport = () => {
    const terms = Array.from(
      new Set(
        bulkWords
          .split(/\r?\n/)
          .map((line) => line.trim())
          .filter(Boolean),
      ),
    );
    if (terms.length === 0) {
      notify("请先粘贴需要加入的单词，每行一个。");
      return;
    }
    const added = addManyInsights(
      terms.map((term) => fallbackInsight(term)),
      "自定义单词本",
      "逐行粘贴导入",
    );
    notify(
      added > 0
        ? `已收录 ${added} 个新词`
        : "这些单词已经在单词本里了",
    );
    setBulkWords("");
    if (added > 0) {
      setInsertOpen(false);
      setActiveChapter("all");
      setSelectedWordId(null);
    }
  };

  const handleSpellingSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!currentSessionWord || !spellingInput.trim()) return;
    setSpellingChecked(true);
  };

  const handleSpellingNext = () => {
    if (!currentSessionWord) return;
    const answer = spellingInput.trim().toLowerCase();
    const expected = currentSessionWord.term.trim().toLowerCase();
    const distance = spellingDistance(answer, expected);
    gradeCurrentWord(
      distance === 0 ? "good" : distance <= 2 ? "hard" : "again",
    );
  };

  const spellingExact =
    spellingChecked &&
    currentSessionWord &&
    spellingInput.trim().toLowerCase() ===
      currentSessionWord.term.trim().toLowerCase();
  const spellingClose =
    spellingChecked &&
    currentSessionWord &&
    !spellingExact &&
    spellingDistance(
      spellingInput.trim().toLowerCase(),
      currentSessionWord.term.trim().toLowerCase(),
    ) <= 2;

  const chapterCount = (chapterId: ChapterId) => {
    if (chapterId === "all") return words.length;
    if (chapterId === "bookmarked") return bookmarkedIds.size;
    return counts[chapterId];
  };

  if (!initialized) {
    return (
      <div className="wordbook-loading">
        <LoaderCircle size={30} />
        <span>Opening your wordbook</span>
      </div>
    );
  }

  return (
    <section className="wordbook-page" data-motion="enter">
      <header className="wordbook-toolbar">
        <button
          type="button"
          className="wordbook-icon-button"
          onClick={() => navigate("/library")}
          aria-label="返回知识库"
          title="返回知识库"
        >
          <ArrowLeft size={18} />
        </button>
        <div className="wordbook-toolbar__title">
          <span>Personal lexicon</span>
          <strong>我的单词本</strong>
        </div>
        <div className="wordbook-toolbar__status">
          <span>
            <Clock3 size={14} />
            今日复习 <strong>{dueWords.length}</strong>
          </span>
          <i />
          <span>
            已掌握 <strong>{counts.mastered}</strong>
          </span>
        </div>
        <div className="wordbook-toolbar__actions">
          <button
            type="button"
            className="wordbook-tool-button"
            onClick={() => setInsertOpen(true)}
          >
            <BookmarkPlus size={16} />
            <span>收录新词</span>
          </button>
          <button
            type="button"
            className="wordbook-icon-button"
            onClick={() => setSettingsOpen(true)}
            aria-label="自定义单词本"
            title="自定义单词本"
          >
            <Settings2 size={17} />
          </button>
          <button
            type="button"
            className="wordbook-tool-button wordbook-tool-button--primary"
            onClick={() => (session ? closeReview() : startReview())}
            disabled={words.length === 0}
          >
            <BookCheck size={16} />
            <span>{session ? "结束复习" : "书中复习"}</span>
          </button>
        </div>
      </header>

      <main className="wordbook-scene">
        <div className="wordbook-book">
          <article className="wordbook-leaf wordbook-leaf--left">
            <div className="wordbook-page-sheet">
              <header className="wordbook-contents-head">
                <span>Contents</span>
                <h1>{book.name}</h1>
                <p>{book.description}</p>
              </header>

              <label className="wordbook-search">
                <Search size={16} />
                <input
                  type="search"
                  value={query}
                  onChange={(event) => setQuery(event.target.value)}
                  placeholder="查找单词、释义或来源"
                />
                {query && (
                  <button
                    type="button"
                    onClick={() => setQuery("")}
                    aria-label="清除搜索"
                  >
                    <X size={14} />
                  </button>
                )}
              </label>

              <nav className="wordbook-chapters" aria-label="单词本目录">
                {chapterDefinitions.map((chapter) => (
                  <button
                    type="button"
                    key={chapter.id}
                    className={cn(
                      activeChapter === chapter.id && "is-active",
                    )}
                    onClick={() => selectChapter(chapter.id)}
                  >
                    <span>{chapter.numeral}</span>
                    <span>
                      <strong>{chapter.title}</strong>
                      <small>{chapter.subtitle}</small>
                    </span>
                    <em>{chapterCount(chapter.id)}</em>
                  </button>
                ))}
              </nav>

              <section className="wordbook-index">
                <header>
                  <span>
                    {currentChapter.title} · {currentChapter.subtitle}
                  </span>
                  <small>{chapterWords.length} entries</small>
                </header>
                <div className="wordbook-index__list">
                  {chapterWords.map((word, index) => (
                    <button
                      type="button"
                      key={word.id}
                      className={cn(
                        "wordbook-index__entry",
                        selectedWord?.id === word.id && "is-active",
                      )}
                      onClick={() => selectWord(word.id)}
                    >
                      <span>{String(index + 1).padStart(2, "0")}</span>
                      <span>
                        <strong>{word.term}</strong>
                        <small>{word.meaningsZh.join("；")}</small>
                      </span>
                      {bookmarkedIds.has(word.id) ? (
                        <BookmarkCheck size={14} />
                      ) : (
                        <ChevronRight size={14} />
                      )}
                    </button>
                  ))}
                  {chapterWords.length === 0 && (
                    <div className="wordbook-index__empty">
                      <Search size={20} />
                      <strong>这一章还没有词条</strong>
                      <span>换一个章节，或收录新词。</span>
                    </div>
                  )}
                </div>
              </section>

              <footer className="wordbook-page-footer">
                <span>{book.subtitle}</span>
                <strong>{activeChapterNumber}</strong>
              </footer>
            </div>
          </article>

          <article
            className={cn(
              "wordbook-leaf",
              "wordbook-leaf--right",
              turning && "is-turning",
            )}
          >
            <div
              key={`${turnKey}-${session ? "review" : selectedWord?.id ?? "blank"}`}
              className="wordbook-page-sheet wordbook-page-sheet--entry"
            >
              {session ? (
                <section className="wordbook-review-leaf">
                  <header className="wordbook-review-leaf__head">
                    <div>
                      <span>Review mode</span>
                      <h2>书中复习</h2>
                    </div>
                    <button
                      type="button"
                      className="wordbook-quiet-button"
                      onClick={closeReview}
                    >
                      <ChevronLeft size={15} />
                      回到词页
                    </button>
                  </header>

                  {session.completed ? (
                    <div className="wordbook-review-complete">
                      <span>
                        <Check size={30} />
                      </span>
                      <small>Two rounds complete</small>
                      <h2>这一页复习完成</h2>
                      <p>
                        共复习 {session.wordIds.length * 2} 次。下一组单词会按艾宾浩斯
                        间隔重新出现。
                      </p>
                      <button
                        type="button"
                        className="wordbook-tool-button wordbook-tool-button--primary"
                        onClick={closeReview}
                      >
                        <BookCheck size={16} />
                        合上复习页
                      </button>
                    </div>
                  ) : currentSessionWord ? (
                    <>
                      <div className="wordbook-review-progress">
                        <span>
                          Round {session.round} of 2 ·{" "}
                          {Math.min(session.index + 1, session.wordIds.length)}/
                          {session.wordIds.length}
                        </span>
                        <i>
                          <span
                            style={{
                              width: `${
                                ((session.index +
                                  (session.completed ? 1 : 0)) /
                                  session.wordIds.length) *
                                100
                              }%`,
                            }}
                          />
                        </i>
                      </div>

                      <div className="wordbook-review-controls">
                        <div>
                          <button
                            type="button"
                            className={cn(
                              reviewMode === "flashcard" && "is-active",
                            )}
                            onClick={() => setReviewMode("flashcard")}
                          >
                            <RotateCcw size={14} />
                            翻卡
                          </button>
                          <button
                            type="button"
                            className={cn(
                              reviewMode === "spelling" && "is-active",
                            )}
                            onClick={() => setReviewMode("spelling")}
                          >
                            <Keyboard size={14} />
                            拼写
                          </button>
                        </div>
                        <div>
                          {(
                            [
                              ["english-chinese", "英 → 中"],
                              ["chinese-english", "中 → 英"],
                            ] as Array<[ReviewDirection, string]>
                          ).map(([direction, label]) => (
                            <button
                              type="button"
                              key={direction}
                              className={cn(
                                reviewDirection === direction && "is-active",
                              )}
                              onClick={() => setReviewDirection(direction)}
                            >
                              {label}
                            </button>
                          ))}
                        </div>
                      </div>

                      {reviewMode === "flashcard" ? (
                        <>
                          <button
                            type="button"
                            className={cn(
                              "wordbook-review-card",
                              flipped && "is-flipped",
                            )}
                            onClick={() => setFlipped((value) => !value)}
                            aria-label="翻动复习卡"
                          >
                            <span className="wordbook-review-card__inner">
                              <span className="wordbook-review-card__face">
                                <small>
                                  {reviewDirection === "english-chinese"
                                    ? `${currentSessionWord.partOfSpeech ?? "expression"} · ${currentSessionWord.cefr ?? "B1-B2"}`
                                    : "根据中文回忆英文"}
                                </small>
                                <strong>
                                  {reviewDirection === "english-chinese"
                                    ? currentSessionWord.term
                                    : currentSessionWord.meaningsZh.join("；")}
                                </strong>
                                <em>
                                  {reviewDirection === "english-chinese"
                                    ? currentSessionWord.pronunciation
                                    : currentSessionWord.definitionEn}
                                </em>
                                <span>
                                  <RotateCcw size={13} />
                                  点击翻页
                                </span>
                              </span>
                              <span className="wordbook-review-card__face is-back">
                                <small>{stageLabel(currentSessionWord)}</small>
                                <strong>
                                  {reviewDirection === "english-chinese"
                                    ? currentSessionWord.meaningsZh.join("；")
                                    : currentSessionWord.term}
                                </strong>
                                <em>
                                  {reviewDirection === "english-chinese"
                                    ? currentSessionWord.definitionEn
                                    : currentSessionWord.meaningsZh.join("；")}
                                </em>
                                {currentSessionWord.examples[0] && (
                                  <blockquote>
                                    {currentSessionWord.examples[0].text}
                                  </blockquote>
                                )}
                              </span>
                            </span>
                          </button>
                          <div className="wordbook-review-ratings">
                            {(
                              [
                                ["again", "忘记了", "明天重来"],
                                ["hard", "有点难", "保持间隔"],
                                ["good", "记住了", "进入下一阶段"],
                                ["easy", "很轻松", "跳过一个阶段"],
                              ] as Array<[ReviewRating, string, string]>
                            ).map(([rating, label, hint]) => (
                              <button
                                type="button"
                                key={rating}
                                className={`is-${rating}`}
                                onClick={() => gradeCurrentWord(rating)}
                                disabled={!flipped}
                              >
                                <strong>{label}</strong>
                                <small>{hint}</small>
                              </button>
                            ))}
                          </div>
                        </>
                      ) : (
                        <form
                          className="wordbook-spelling-leaf"
                          onSubmit={handleSpellingSubmit}
                        >
                          <small>
                            {currentSessionWord.partOfSpeech ?? "expression"} ·{" "}
                            {currentSessionWord.cefr ?? "B1-B2"}
                          </small>
                          <h3>{currentSessionWord.meaningsZh.join("；")}</h3>
                          <p>{currentSessionWord.definitionEn}</p>
                          <div className="wordbook-spelling-hint">
                            <span>{currentSessionWord.term.slice(0, 1)}</span>
                            {Array.from({
                              length: Math.max(
                                1,
                                currentSessionWord.term.length - 1,
                              ),
                            }).map((_, index) => (
                              <span key={index}>_</span>
                            ))}
                          </div>
                          <label>
                            <Keyboard size={16} />
                            <input
                              value={spellingInput}
                              onChange={(event) =>
                                setSpellingInput(event.target.value)
                              }
                              placeholder="在这里拼写英文"
                              autoFocus
                              spellCheck={false}
                            />
                          </label>
                          {spellingChecked ? (
                            <div
                              className={cn(
                                "wordbook-spelling-result",
                                spellingExact && "is-correct",
                                spellingClose && "is-close",
                                !spellingExact &&
                                  !spellingClose &&
                                  "is-wrong",
                              )}
                            >
                              {spellingExact ? (
                                <>
                                  <Check size={16} />
                                  拼写正确
                                </>
                              ) : spellingClose ? (
                                <>接近了，再核对一个字母。</>
                              ) : (
                                <>再想一想，正确形式是 {currentSessionWord.term}</>
                              )}
                            </div>
                          ) : (
                            <button
                              type="submit"
                              className="wordbook-tool-button wordbook-tool-button--primary"
                              disabled={!spellingInput.trim()}
                            >
                              检查拼写
                            </button>
                          )}
                          {spellingChecked && (
                            <button
                              type="button"
                              className="wordbook-tool-button wordbook-tool-button--primary"
                              onClick={handleSpellingNext}
                            >
                              继续下一页
                              <ChevronRight size={15} />
                            </button>
                          )}
                        </form>
                      )}
                    </>
                  ) : (
                    <div className="wordbook-page-empty">
                      <BookOpen size={28} />
                      <strong>复习队列暂时不可用</strong>
                      <button type="button" onClick={closeReview}>
                        返回词页
                      </button>
                    </div>
                  )}
                </section>
              ) : selectedWord ? (
                <section className="wordbook-entry">
                  <header className="wordbook-entry__head">
                    <div>
                      <span>
                        {stageLabel(selectedWord)} ·{" "}
                        {selectedWord.sourceLabel}
                      </span>
                      <h2>
                        <HighlightedText
                          text={selectedWord.term}
                          term={selectedWord.term}
                          active={highlightedIds.has(selectedWord.id)}
                          onToggle={() => toggleHighlight(selectedWord.id)}
                        />
                      </h2>
                      <p>
                        {selectedWord.pronunciation ??
                          selectedWord.lemma}{" "}
                        · {selectedWord.partOfSpeech ?? "expression"} ·{" "}
                        {selectedWord.cefr ?? "B1-B2"}
                      </p>
                    </div>
                    <div className="wordbook-entry__tools">
                      <button
                        type="button"
                        onClick={() =>
                          speak(selectedWord.term) ||
                          notify("当前浏览器不支持语音朗读")
                        }
                        aria-label="朗读单词"
                        title="朗读单词"
                      >
                        <Volume2 size={16} />
                      </button>
                      <button
                        type="button"
                        className={cn(
                          highlightedIds.has(selectedWord.id) && "is-active",
                        )}
                        onClick={() => toggleHighlight(selectedWord.id)}
                        aria-label="标记高亮"
                        title="标记高亮"
                      >
                        <Highlighter size={16} />
                      </button>
                      <button
                        type="button"
                        className="is-desktop-only"
                        onClick={() => noteRef.current?.focus()}
                        aria-label="写页边笔记"
                        title="写页边笔记"
                      >
                        <PenLine size={16} />
                      </button>
                    </div>
                  </header>

                  <section className="wordbook-entry__meaning">
                    <span>Meaning</span>
                    <p>{selectedWord.meaningsZh.join("；")}</p>
                  </section>

                  <section className="wordbook-entry__definition">
                    <span>Definition</span>
                    <p>
                      <HighlightedText
                        text={selectedWord.definitionEn}
                        term={selectedWord.term}
                        active={highlightedIds.has(selectedWord.id)}
                        onToggle={() => toggleHighlight(selectedWord.id)}
                      />
                    </p>
                  </section>

                  <section className="wordbook-entry__collocations">
                    <span>Collocations</span>
                    <div>
                      {selectedWord.collocations.map((collocation) => (
                        <button
                          type="button"
                          key={collocation}
                          onClick={() => {
                            setDictionaryQuery(collocation);
                            setInsertOpen(true);
                            void lookupDictionary(collocation);
                          }}
                        >
                          {collocation}
                        </button>
                      ))}
                    </div>
                  </section>

                  {selectedWord.examples[0] && (
                    <section className="wordbook-entry__example">
                      <span>In context</span>
                      <blockquote>
                        <HighlightedText
                          text={selectedWord.examples[0].text}
                          term={selectedWord.term}
                          active={highlightedIds.has(selectedWord.id)}
                          onToggle={() => toggleHighlight(selectedWord.id)}
                        />
                      </blockquote>
                      {selectedWord.examples[0].translationZh && (
                        <small>
                          {selectedWord.examples[0].translationZh}
                        </small>
                      )}
                    </section>
                  )}

                  <label className="wordbook-margin-note">
                    <span>
                      <PenLine size={14} />
                      Marginalia
                    </span>
                    <textarea
                      ref={noteRef}
                      value={notes[selectedWord.id] ?? ""}
                      onChange={(event) =>
                        setNotes((current) => ({
                          ...current,
                          [selectedWord.id]: event.target.value,
                        }))
                      }
                      placeholder="在页边写下记忆线索、近义词或自己的例句……"
                      spellCheck={false}
                    />
                  </label>

                  <footer className="wordbook-entry__footer">
                    <span>
                      {dueText(selectedWord)} · 已复习{" "}
                      {selectedWord.reviewCount} 次
                    </span>
                    <button
                      type="button"
                      onClick={() => {
                        removeWord(selectedWord.id);
                        setSelectedWordId(null);
                        notify("已从单词本移除");
                      }}
                    >
                      <Trash2 size={14} />
                      移除
                    </button>
                  </footer>
                </section>
              ) : (
                <div className="wordbook-page-empty">
                  <BookOpen size={28} />
                  <strong>选择左侧目录中的词条</strong>
                  <p>词义、搭配、例句和页边手记会显示在这一页。</p>
                </div>
              )}
            </div>

            {selectedWord && !session && (
              <button
                type="button"
                className={cn(
                  "wordbook-ribbon",
                  bookmarkedIds.has(selectedWord.id) && "is-active",
                )}
                onClick={() => toggleBookmark(selectedWord.id)}
                aria-label={
                  bookmarkedIds.has(selectedWord.id)
                    ? "移除书签"
                    : "为当前词条加书签"
                }
                title={
                  bookmarkedIds.has(selectedWord.id)
                    ? "移除书签"
                    : "为当前词条加书签"
                }
              >
                {bookmarkedIds.has(selectedWord.id) ? (
                  <BookmarkCheck size={16} />
                ) : (
                  <Bookmark size={16} />
                )}
              </button>
            )}

            <footer className="wordbook-page-footer wordbook-page-footer--right">
              <span>
                {currentWordIndex >= 0
                  ? `Entry ${currentWordIndex + 1}`
                  : session
                    ? "Review"
                    : book.subtitle}
              </span>
              <strong>
                {currentWordIndex >= 0
                  ? activeChapterNumber + currentWordIndex * 2 + 1
                  : activeChapterNumber + 1}
              </strong>
            </footer>
          </article>

          <span className="wordbook-spine" aria-hidden="true" />
        </div>
      </main>

      {notice && <div className="wordbook-notice">{notice}</div>}

      {settingsOpen && (
        <BookSettings
          onClose={() => setSettingsOpen(false)}
          onSave={(patch) => {
            updateBook(patch);
            setSettingsOpen(false);
            notify("单词本封面已更新");
          }}
        />
      )}

      {insertOpen && (
        <div
          className="wordbook-modal"
          role="presentation"
          onClick={() => setInsertOpen(false)}
        >
          <div
            className="wordbook-insert-dialog"
            role="dialog"
            aria-modal="true"
            aria-label="收录新词"
            onClick={(event) => event.stopPropagation()}
          >
            <header>
              <div>
                <span>New entry</span>
                <h2>收录新词</h2>
              </div>
              <button
                type="button"
                className="wordbook-icon-button"
                onClick={() => setInsertOpen(false)}
                aria-label="关闭"
              >
                <X size={17} />
              </button>
            </header>

            <div className="wordbook-insert-grid">
              <section>
                <header>
                  <Languages size={17} />
                  <span>
                    <strong>Oxford Learner's</strong>
                    <small>
                      {dictionaryStatus?.available
                        ? `${dictionaryStatus.name} · ${dictionaryStatus.wordCount.toLocaleString()} words`
                        : "输入单词，创建一页新的词条"}
                    </small>
                  </span>
                </header>
                <form onSubmit={handleDictionarySearch}>
                  <Search size={15} />
                  <input
                    value={dictionaryQuery}
                    onChange={(event) => setDictionaryQuery(event.target.value)}
                    placeholder="查询单词或短语"
                  />
                  <button type="submit" aria-label="查询">
                    {dictionaryLoading ? (
                      <LoaderCircle size={15} />
                    ) : (
                      <ChevronRight size={15} />
                    )}
                  </button>
                </form>
                {dictionaryResult && (
                  <article className="wordbook-dictionary-result">
                    <strong>{dictionaryResult.term}</strong>
                    <small>
                      {dictionaryResult.partOfSpeech ?? "expression"} ·{" "}
                      {dictionaryResult.pronunciation ?? "IPA pending"}
                    </small>
                    <p>{dictionaryResult.meaningsZh.join("；")}</p>
                    <span>{dictionaryResult.definitionEn}</span>
                    <button
                      type="button"
                      className="wordbook-tool-button wordbook-tool-button--primary"
                      onClick={handleDictionaryAdd}
                    >
                      <BookmarkPlus size={15} />
                      收进单词本
                    </button>
                  </article>
                )}
              </section>

              <section>
                <header>
                  <PenLine size={17} />
                  <span>
                    <strong>手写目录</strong>
                    <small>一行一个单词或短语，批量生成词页。</small>
                  </span>
                </header>
                <textarea
                  value={bulkWords}
                  onChange={(event) => setBulkWords(event.target.value)}
                  placeholder={"solitude\ncompetitive edge\nin the wake of"}
                  spellCheck={false}
                />
                <button
                  type="button"
                  className="wordbook-tool-button wordbook-tool-button--primary"
                  onClick={handleBulkWordImport}
                  disabled={!bulkWords.trim()}
                >
                  创建词页
                </button>
              </section>
            </div>

            <footer>
              <button
                type="button"
                className="wordbook-quiet-button"
                onClick={() => {
                  const existing = new Set(
                    words.map((word) => word.term.toLowerCase()),
                  );
                  const additions = corpus.filter(
                    (entry) => !existing.has(entry.term.toLowerCase()),
                  );
                  if (additions.length === 0) {
                    notify("语料库中的表达已经全部收录");
                    return;
                  }
                  for (const entry of additions) {
                    useVocabulary.getState().addCorpusEntry(entry);
                  }
                  setInsertOpen(false);
                  setActiveChapter("all");
                  setSelectedWordId(null);
                  notify(`从语料库收录了 ${additions.length} 个表达`);
                }}
              >
                <BookOpen size={15} />
                从语料库收录
              </button>
            </footer>
          </div>
        </div>
      )}
    </section>
  );
}

function BookSettings({
  onClose,
  onSave,
}: {
  onClose: () => void;
  onSave: (patch: {
    name: string;
    subtitle: string;
    description: string;
    theme: VocabularyCoverTheme;
    accent: string;
  }) => void;
}) {
  const book = useVocabulary((state) => state.book);
  const [name, setName] = useState(book.name);
  const [subtitle, setSubtitle] = useState(book.subtitle);
  const [description, setDescription] = useState(book.description);
  const [theme, setTheme] = useState<VocabularyCoverTheme>(book.theme);
  const selectedTheme =
    COVER_THEMES.find((item) => item.id === theme) ?? COVER_THEMES[0]!;

  return (
    <div className="wordbook-modal" role="presentation" onClick={onClose}>
      <div
        className="wordbook-settings-dialog"
        role="dialog"
        aria-modal="true"
        aria-label="自定义单词本"
        onClick={(event) => event.stopPropagation()}
      >
        <header>
          <div>
            <span>Book identity</span>
            <h2>自定义单词本</h2>
          </div>
          <button
            type="button"
            className="wordbook-icon-button"
            onClick={onClose}
            aria-label="关闭"
          >
            <X size={17} />
          </button>
        </header>

        <div className="wordbook-settings-layout">
          <div
            className="wordbook-cover wordbook-cover--preview"
            style={coverStyle(theme, selectedTheme.accent)}
          >
            <span className="wordbook-cover__spine" />
            <span className="wordbook-cover__rule" />
            <small>LEAFIA · PERSONAL EDITION</small>
            <strong>{name || "我的单词本"}</strong>
            <em>{subtitle || "A personal vocabulary book"}</em>
            <i>WORDBOOK</i>
          </div>

          <div className="wordbook-settings-fields">
            <label>
              <span>书本名称</span>
              <input
                value={name}
                onChange={(event) => setName(event.target.value)}
                maxLength={28}
                autoFocus
              />
            </label>
            <label>
              <span>副标题</span>
              <input
                value={subtitle}
                onChange={(event) => setSubtitle(event.target.value)}
                maxLength={48}
              />
            </label>
            <label>
              <span>书内说明</span>
              <textarea
                value={description}
                onChange={(event) => setDescription(event.target.value)}
                maxLength={140}
              />
            </label>
            <fieldset>
              <legend>封面配色</legend>
              <div className="wordbook-theme-swatches">
                {COVER_THEMES.map((item) => (
                  <button
                    type="button"
                    key={item.id}
                    className={cn(theme === item.id && "is-active")}
                    onClick={() => setTheme(item.id)}
                    aria-label={item.label}
                    title={item.label}
                  >
                    <i style={{ background: item.accent }} />
                    <span style={{ background: item.secondary }} />
                    {theme === item.id && <Check size={13} />}
                  </button>
                ))}
              </div>
            </fieldset>
          </div>
        </div>

        <footer>
          <button
            type="button"
            className="wordbook-quiet-button"
            onClick={onClose}
          >
            取消
          </button>
          <button
            type="button"
            className="wordbook-tool-button wordbook-tool-button--primary"
            onClick={() =>
              onSave({
                name: name.trim() || "我的单词本",
                subtitle:
                  subtitle.trim() || "A personal vocabulary book",
                description:
                  description.trim() ||
                  "从阅读、词典查询和语料库中收集的个人英语词汇。",
                theme,
                accent: selectedTheme.accent,
              })
            }
          >
            <Check size={16} />
            保存
          </button>
        </footer>
      </div>
    </div>
  );
}
